export const runtime = "nodejs";

type Brief = {
  institutionName:string; institutionType:string; department:string; planType:string; audience:string; audienceLevel:string; audienceCount:string;
  topic:string; problem:string; purpose:string; objectives:string[]; totalMinutes:string; sessions:string;
  deliveryMethod:string; practiceRatio:string; devices:string; accountEnvironment:string; designRequest:string; designReferenceUrl:string; designPreset:string; notionUrl:string; deadline:string; location:string; budget:string; finalDeliverable:string;
};

type Content = { title:string; subtitle:string; summary:string; sections:{title:string; bullets:string[]}[]; practices:{id:string;title:string;steps:string[];output:string}[] };

function safe(value:string){return (value||"강의프로젝트").replace(/[\\/:*?"<>|]/g,"_").replace(/\s+/g,"_").slice(0,60)}
function josa(word:string,pair:"이가"|"을를"|"은는"){const last=word.trim().charCodeAt(word.trim().length-1);const hasFinal=last>=0xAC00&&last<=0xD7A3&&(last-0xAC00)%28!==0;const map={이가:hasFinal?"이":"가",을를:hasFinal?"을":"를",은는:hasFinal?"은":"는"};return `${word}${map[pair]}`}

function defaultContent(brief:Brief,stage:string):Content{
  const topic=brief.topic||"생성형 AI 활용"; const audience=brief.audience||"교육 참여자"; const institution=brief.institutionName||brief.institutionType||"교육기관";
  const plan=classifyPlan(brief.institutionType,brief.audience,brief.topic,brief.purpose,brief.planType);
  const goals=brief.objectives?.length?brief.objectives:[`${topic}의 핵심 개념을 설명할 수 있다.`,`${topic}을 활용한 결과물을 완성할 수 있다.`,`완성한 결과물을 검토하고 개선할 수 있다.`];
  const common={title:`${topic} 교육`,subtitle:`${institution} · ${audience} · ${brief.totalMinutes||"시간 미정"}`,summary:`${plan.name} 기준으로 ${josa(audience,"이가")} ${josa(topic,"을를")} 실제 상황에 적용하고 ${brief.finalDeliverable||"구체적인 결과물"}을 완성하도록 설계한 교육입니다.`};
  if(stage==="proposal")return {...common,title:`${topic} 교육 제안서`,sections:[{title:"제안 배경",bullets:[brief.problem||`${audience}에게는 도구 소개를 넘어 실제 적용 경험이 필요합니다.`,`지금 필요한 지식과 실행을 한 과정 안에서 연결합니다.`]},{title:"교육 후 변화",bullets:goals},{title:"운영 방법",bullets:[brief.deliveryMethod||"설명과 실습을 균형 있게 진행",`총 ${brief.totalMinutes||"미정"}, ${brief.sessions||"1"}차시`,`참여자가 결과물을 직접 완성하고 점검하도록 운영`]},{title:"기대 결과물",bullets:[`${topic} 적용 결과물 1개`,`재사용 가능한 실행 절차와 프롬프트`,`교육 후 바로 실행할 체크리스트`]}],practices:[]};
  if(stage==="curriculum")return {...common,title:`${topic} 세부커리큘럼`,sections:[{title:"도입 · 문제와 목표",bullets:["현재 어려움과 교육 목표 확인","오늘 완성할 결과물 안내","도구·계정·안전 조건 점검"]},{title:"핵심 이해",bullets:[`${topic}의 핵심 개념`,`좋은 결과와 부족한 결과 비교`,`판단 기준과 주의사항`]},{title:"시연과 따라하기",bullets:["강사 시연","단계별 따라하기","결과 확인과 오류 대안"]},{title:"개별 적용과 정리",bullets:["자신의 상황에 맞게 수정","결과물 점검과 피드백","교육 후 실행계획 작성"]}],practices:[{id:"PRACTICE-01",title:"핵심 결과물 따라 만들기",steps:["준비정보 3가지를 정한다.","기본 입력문을 실행한다.","결과를 확인하고 한 번 수정한다."],output:`${topic} 1차 결과물`},{id:"PRACTICE-02",title:"내 상황에 맞게 적용하기",steps:["실제 상황으로 입력값을 바꾼다.","판단 기준으로 결과를 점검한다.","최종본과 다음 행동을 기록한다."],output:"개인별 적용 결과물"}]};
  if(stage==="ppt")return {...common,title:`${topic} 강의자료`,sections:[
    {title:"생성형 AI를 제대로 이해하기",bullets:["검색은 이미 존재하는 정보를 찾고, 생성형 AI는 입력 조건을 바탕으로 새로운 답안을 구성합니다.","답변이 자연스러워도 사실과 다를 수 있으므로 결과물은 초안으로 다룹니다.","업무의 목적·대상·형식이 분명할수록 수정 횟수를 줄일 수 있습니다.","중요한 판단과 최종 책임은 사용자에게 있습니다."]},
    {title:"좋은 요청의 5가지 구성",bullets:["역할: 누구의 관점으로 답할지 정합니다.","목적: 결과물을 어디에 사용할지 설명합니다.","맥락: 대상·상황·보유 정보를 제공합니다.","형식: 표, 목록, 문서 분량 등 출력 규격을 지정합니다.","검토 기준: 정확성·누락·톤·실행 가능성을 확인하게 합니다."]},
    {title:"업무 적용 시나리오",bullets:[`${josa(audience,"이가")} 반복 작성하는 안내문·이메일·보고 초안을 빠르게 구조화합니다.`,`회의 메모에서 결정사항·담당자·기한을 분리합니다.`,`긴 자료를 대상별 설명 수준에 맞춰 요약하고 질문 목록을 만듭니다.`,`하나의 초안을 공문형·친절형·간결형으로 변환해 비교합니다.`]},
    {title:"초안에서 완성본으로",bullets:["첫 답변을 그대로 쓰지 않고 누락과 모호한 표현을 표시합니다.","한 번에 전부 다시 쓰기보다 부족한 부분만 구체적으로 수정 요청합니다.","기관 용어, 고유명사, 날짜와 수치는 원문과 대조합니다.","최종본은 사람이 읽고 목적과 대상에 맞는지 승인합니다."]},
    {title:"사실 확인과 안전",bullets:["개인정보·민감정보·비공개 자료는 입력하지 않습니다.","법률·의료·재무 등 고위험 정보는 공식 자료와 전문가를 통해 재확인합니다.","출처가 필요한 문장은 근거 링크와 발행일을 별도로 확인합니다.","이미지·문구 사용 전 저작권과 기관 내부 기준을 확인합니다."]},
    {title:"실패 사례를 개선하는 법",bullets:["막연한 요청은 일반적인 답을 만듭니다. 실제 독자와 사용 장면을 추가합니다.","내용이 길면 우선 목차만 만든 뒤 항목별로 확장합니다.","톤이 맞지 않으면 참고 문장과 금지 표현을 함께 제시합니다.","결과가 흔들리면 완료 기준을 체크리스트로 고정합니다."]},
    {title:"현장 적용 체크리스트",bullets:["이 작업에 AI를 써도 되는가?","입력 정보에서 민감정보를 제거했는가?","원하는 결과물의 독자와 목적이 명확한가?","사실·수치·고유명사를 원문과 대조했는가?","최종 결정자가 검토했는가?"]},
    {title:"교육 후 실행 계획",bullets:["이번 주 반복 업무 한 가지를 선택합니다.","오늘 만든 프롬프트를 실제 정보에 맞게 수정합니다.","절약 시간보다 정확도와 수정 횟수를 먼저 기록합니다.","좋았던 프롬프트와 실패 원인을 팀의 공용 자산으로 남깁니다."]}
  ],practices:[{id:"PRACTICE-01",title:"업무 요청을 구조화한 프롬프트 만들기",steps:["실제 업무 하나를 고르고 독자·목적·보유자료를 적습니다.","역할·맥락·출력형식·완료기준을 포함한 프롬프트를 작성합니다.","결과에서 누락·모호함·사실 확인 항목을 표시합니다."],output:"재사용 가능한 업무 프롬프트와 1차 초안"},{id:"PRACTICE-02",title:"초안을 기관용 완성본으로 개선하기",steps:["기관 용어와 실제 정보로 입력값을 교체합니다.","톤·분량·금지 표현을 지정해 부분 수정합니다.","개인정보·사실·출처·실행 가능성 체크 후 최종본을 저장합니다."],output:"검수 체크가 완료된 최종 결과물"}]};
  if(stage==="script")return {...common,title:`${topic} 발표스크립트`,sections:[{title:"S1 · 표지",bullets:[`안녕하세요. 오늘은 ${topic}을 함께 살펴보겠습니다.`,`오늘의 목표는 이해에 그치지 않고 실제 결과물 하나를 완성하는 것입니다.`,`먼저 기기와 계정 준비 상태를 확인하겠습니다.`]},{title:"S2 · 오늘의 목표",bullets:goals.map(g=>`${g} 이 목표를 중심으로 설명과 실습을 연결하겠습니다.`)},{title:"S3 · 왜 필요한가",bullets:[brief.problem||`${audience}가 현장에서 겪는 어려움을 먼저 확인하겠습니다.`,`도구 자체보다 어떤 상황에서 어떻게 사용할지가 중요합니다.`]},{title:"S4~S8 · 개념·사례·실습",bullets:["핵심 개념을 실제 사례로 설명합니다.","화면 시연 후 참여자가 같은 순서로 따라 합니다.","오류가 발생하면 준비된 대체 화면과 설명 경로를 사용합니다."]},{title:"S9 · 정리",bullets:["오늘 만든 결과물을 다시 확인해주세요.","가장 먼저 실행할 행동 한 가지를 정해주세요.","질문을 받고 교육을 마무리하겠습니다."]}],practices:[]};
  if(stage==="architecture")return {...defaultContent(brief,"ppt"),title:`${topic} PPT 콘텐츠 설계`,subtitle:common.subtitle,summary:`교육목표와 실습 결과물에서 역산한 ${topic} PPT 구성안입니다.`};
  if(stage==="design")return {...common,title:`${topic} 맞춤 디자인 가이드`,summary:`${institution}의 신뢰도와 ${audience}의 가독성을 함께 반영한 발표 디자인 기준입니다.`,sections:[{title:"비주얼 콘셉트",bullets:[brief.designRequest||"전문적이고 명료한 기관형 에디토리얼 스타일",`추천 디자인 시스템: ${resolveDesign(brief.designPreset,brief.institutionType,brief.audience,brief.topic).name}`,"장식보다 정보 위계와 실제 사례의 이해를 우선합니다."]},{title:"타이포그래피",bullets:["한글 제목은 굵고 짧게, 본문은 22pt 이상을 유지합니다.","문단 간 여백을 충분히 두고 한 슬라이드의 핵심 메시지를 하나로 제한합니다.","긴 문장은 비교·프로세스·체크리스트 구조로 전환합니다."]},{title:"시각자료 원칙",bullets:["실제 화면·대상 맞춤 이미지·데이터 차트를 내용 근거와 함께 배치합니다.","이모지는 강조 표식으로만 제한적으로 사용합니다.","같은 레이아웃이 3장 이상 이어지지 않게 구성합니다."]}],practices:[]};
  if(stage==="final_qa")return {...common,title:`${topic} 최종 품질검수`,summary:"승인된 기준정보와 결과물의 연결 상태를 확인한 최종 검수 결과입니다.",sections:[{title:"기준정보 일치",bullets:[`기관: ${institution}`,`대상: ${audience}`,`교육시간: ${brief.totalMinutes||"[직접 입력]"}`,`최종 결과물: ${brief.finalDeliverable||"[직접 입력]"}`]},{title:"교차 연결",bullets:["교육목표와 커리큘럼 결과물 연결 확인","PPT 실습 ID와 Notion PRACTICE ID 연결 확인","발표스크립트의 슬라이드 번호 연결 확인"]},{title:"최종 확인사항",bullets:["날짜·수치·기관 정책은 담당자가 원문과 대조합니다.","개인정보·저작권·출처를 최종 확인합니다.","실제 수업 전 기기·계정·인터넷 환경을 점검합니다."]}],practices:[]};
  return {...common,title:`${topic} 강의기획서`,sections:[{title:"교육 개요",bullets:[`대상: ${audience}${brief.audienceLevel?` (${brief.audienceLevel})`:""}`,`시간: ${brief.totalMinutes||"미정"} · ${brief.sessions||"1"}차시`,`방법: ${brief.deliveryMethod||"설명과 실습"}`,`환경: ${brief.devices||"기기 확인 필요"} · ${brief.accountEnvironment||"계정 확인 필요"}`]},{title:"교육 목적",bullets:[brief.purpose||`${topic}을 실제 상황에서 활용할 수 있는 기초 역량을 기릅니다.`]},{title:"행동형 교육목표",bullets:goals},{title:"교육 흐름",bullets:["도입: 문제와 결과물 확인","이해: 핵심 개념과 사례","시연: 강사 화면으로 실행 과정 확인","실습: 참여자 결과물 완성","정리: 결과 점검과 실행계획"]},{title:"준비와 안전",bullets:[brief.devices||"참여자 기기 준비",brief.accountEnvironment||"사용 도구 계정 준비","개인정보·저작권·사실 확인 원칙 안내"]}],practices:[]};
}

async function createContent(brief:Brief,stage:string){
  const fallback=defaultContent(brief,stage); const apiKey=process.env.OPENAI_API_KEY;
  if(!apiKey)return {content:fallback,ai:false};
  try{
    const client=new OpenAI({apiKey});
    const response=await client.responses.create({model:process.env.OPENAI_MODEL||"gpt-5.4",input:`다음 MASTER BRIEF를 근거로 ${stage} 산출물 콘텐츠를 작성해라. 총 교육시간에 맞춰 이론·시연·실습·피드백을 배분하고, PPT는 최소 8개 주제 섹션과 섹션당 4~5개의 구체적인 메시지, 2개 이상의 실제 실습을 작성한다. 대상이 현장에서 바로 쓸 사례·입력값·완료기준을 포함하고 반복되는 일반론은 제거한다. 확인되지 않은 사실과 수치를 만들지 말고 개인정보·저작권·사실확인 지점을 명시한다. JSON만 출력한다.\n${JSON.stringify(brief)}`,text:{format:{type:"json_schema",name:"lecture_artifact",strict:true,schema:{type:"object",additionalProperties:false,properties:{title:{type:"string"},subtitle:{type:"string"},summary:{type:"string"},sections:{type:"array",items:{type:"object",additionalProperties:false,properties:{title:{type:"string"},bullets:{type:"array",items:{type:"string"}}},required:["title","bullets"]}},practices:{type:"array",items:{type:"object",additionalProperties:false,properties:{id:{type:"string"},title:{type:"string"},steps:{type:"array",items:{type:"string"}},output:{type:"string"}},required:["id","title","steps","output"]}}},required:["title","subtitle","summary","sections","practices"]}}}});
    return {content:JSON.parse(response.output_text) as Content,ai:true};
  }catch{return {content:fallback,ai:false};}
}

function docParagraph(text:string,bold=false,size=21){return new Paragraph({spacing:{after:100,line:300},children:[new TextRun({text,bold,size,font:"Malgun Gothic",color:bold?"173F36":"29332F"})]})}

async function buildDocx(content:Content,brief:Brief){
  const rows=content.sections.map((s)=>new TableRow({children:[new TableCell({width:{size:2200,type:WidthType.DXA},shading:{type:ShadingType.CLEAR,fill:"EAF3DA"},margins:{top:140,bottom:140,left:140,right:140},children:[docParagraph(s.title,true,20)]}),new TableCell({width:{size:6800,type:WidthType.DXA},margins:{top:140,bottom:140,left:180,right:180},children:s.bullets.map(b=>docParagraph(`• ${b}`,false,19))})]}));
  const doc=new Document({styles:{default:{document:{run:{font:"Malgun Gothic",size:21},paragraph:{spacing:{line:300}}}}},sections:[{properties:{page:{size:{width:11906,height:16838},margin:{top:900,right:900,bottom:900,left:900}}},children:[new Paragraph({alignment:AlignmentType.CENTER,spacing:{after:180},children:[new TextRun({text:content.title,bold:true,size:38,font:"Malgun Gothic",color:"173F36"})]}),new Paragraph({alignment:AlignmentType.CENTER,spacing:{after:360},children:[new TextRun({text:content.subtitle,size:19,font:"Malgun Gothic",color:"68736D"})]}),new Paragraph({heading:HeadingLevel.HEADING_1,spacing:{before:100,after:100},children:[new TextRun({text:"제안 요약",bold:true,size:26,font:"Malgun Gothic",color:"173F36"})]}),docParagraph(content.summary,false,21),new Table({width:{size:9000,type:WidthType.DXA},columnWidths:[2200,6800],rows}),new Paragraph({spacing:{before:280},children:[new TextRun({text:`생성 기준 · ${brief.institutionName||brief.institutionType} / ${brief.audience} / ${brief.totalMinutes}`,size:16,font:"Malgun Gothic",color:"8A928E"})]})]}]});
  return Packer.toBuffer(doc);
}

function heading(text:string){return new Paragraph({keepNext:true,spacing:{before:300,after:140,line:320},children:[new TextRun({text,bold:true,size:28,font:"Malgun Gothic",color:"103E52"})]})}
function cleanBullets(items:string[]){return items.map(text=>new Paragraph({bullet:{level:0},spacing:{before:0,after:90,line:290},indent:{left:430,hanging:210},children:[new TextRun({text,size:20,font:"Malgun Gothic",color:"28363B"})]}))}
function infoTable(rows:[string,string][],labelWidth=1700,valueWidth=7300){return new Table({width:{size:9000,type:WidthType.DXA},layout:TableLayoutType.FIXED,columnWidths:[labelWidth,valueWidth],borders:{top:{style:BorderStyle.SINGLE,size:5,color:"AFC2C8"},bottom:{style:BorderStyle.SINGLE,size:5,color:"AFC2C8"},left:{style:BorderStyle.SINGLE,size:5,color:"AFC2C8"},right:{style:BorderStyle.SINGLE,size:5,color:"AFC2C8"},insideHorizontal:{style:BorderStyle.SINGLE,size:3,color:"D8E1E4"},insideVertical:{style:BorderStyle.SINGLE,size:3,color:"D8E1E4"}},rows:rows.map(([label,value])=>new TableRow({children:[new TableCell({width:{size:labelWidth,type:WidthType.DXA},shading:{type:ShadingType.CLEAR,fill:"103E52"},margins:{top:130,bottom:130,left:150,right:150},children:[new Paragraph({alignment:AlignmentType.CENTER,children:[new TextRun({text:label,bold:true,size:18,color:"FFFFFF",font:"Malgun Gothic"})]})]}),new TableCell({width:{size:valueWidth,type:WidthType.DXA},margins:{top:130,bottom:130,left:180,right:180},children:[docParagraph(value,false,19)]})]}))})}

