  for(let si=0;si<content.sections.length;si++){const sec=content.sections[si];s=p.addSlide();s.background={color:c.bg};addSectionArt(s,si);s.addText(`PART ${String(si+1).padStart(2,"0")}`,{x:7.0,y:.82,w:2.2,h:.3,fontFace:"Aptos",fontSize:12,bold:true,charSpacing:2,color:c.primary,margin:0});s.addText(sec.title,{x:6.98,y:1.72,w:5.35,h:1.8,fontFace:"Malgun Gothic",fontSize:39,bold:true,color:c.ink,margin:0,breakLine:false});s.addShape(p.ShapeType.line,{x:7.0,y:3.95,w:1.15,h:0,line:{color:c.accent,width:5}});s.addText(sec.bullets[0]||content.summary,{x:7.02,y:4.42,w:5.1,h:1.2,fontSize:17,color:c.muted,margin:0,breakLine:false});s.addText(String(si+1).padStart(2,"0"),{x:11.4,y:6.38,w:1.0,h:.6,fontFace:"Aptos Display",fontSize:34,bold:true,color:c.primary,margin:0,align:"right"});no++;bulletSlide(sec.title,sec.bullets,no++,emojis[(si+1)%emojis.length]);if(si%2===0){statementSlide(sec.title,sec.bullets[0]||content.summary,sec.bullets[1]||"실제 상황에 적용할 조건을 정합니다.",no++);exampleSlide(`${sec.title} · 현장 적용`,brief.problem||`${josa(brief.audience,"이가")} 실제로 겪는 반복 업무`,sec.bullets[2]||"목적과 완료 기준을 추가해 결과를 개선합니다.",no++)}else{exampleSlide(`${sec.title} · 실제 상황`,sec.bullets[0]||"막연한 요청으로 결과가 흔들리는 상황",sec.bullets[1]||"대상과 목적을 분명히 지정합니다.",no++);processSlide(`${sec.title} · 적용 순서`,[sec.bullets[1]||"조건 정의",sec.bullets[2]||"작게 실행",sec.bullets[3]||"결과 검수"],no++)}}
